#ifdef CONFIG_TRACING

#ifdef CONFIG_MEMCG

static u64 get_mm_memcg_id(struct mm_struct *mm)
{
	struct mem_cgroup *memcg;
	u64 id = 0;

	memcg = get_mem_cgroup_from_mm(mm);
	if (memcg == NULL)
		return 0;
	if (memcg->css.cgroup)
		id = cgroup_id(memcg->css.cgroup);
	css_put(&memcg->css);
	return id;
}

#define TRACE_MMAP_LOCK_EVENT(type, mm, ...)				\
	do {								\
		if (trace_mmap_lock_##type##_enabled()) {		\
			u64 memcg_id = get_mm_memcg_id(mm);		\
			trace_mmap_lock_##type(mm, memcg_id, ##__VA_ARGS__); \
		}							\
	} while (0)

#else /* !CONFIG_MEMCG */

#define TRACE_MMAP_LOCK_EVENT(type, mm, ...)                                   \
	trace_mmap_lock_##type(mm, 0, ##__VA_ARGS__)

#endif /* CONFIG_MEMCG */

